    /// <summary>
    /// Creates the initial player/lobby presentation assets and performs additive,
    /// one-time migration. Existing authored prefab hierarchies are validated and
    /// are never regenerated by the normal multiplayer rebuild.
    /// </summary>
    public static class MultiplayerPresentationPrefabProjectSetup
    {
