            "Assets/MazeParty/Prefabs/Multiplayer/PlayerAvatarPresentation.prefab";
        public const string PlayerWorldIndicatorPrefabPath =
            "Assets/MazeParty/Prefabs/Multiplayer/PlayerWorldIndicator.prefab";
        public const string PlayerPresentationAssetsPath =
            "Assets/MazeParty/Resources/MazeParty/Player/PlayerAvatarPresentationAssets.asset";
        public const string PlayerPrefabPath =
            "Assets/MazeParty/Prefabs/Multiplayer/NetworkPlayer.prefab";
        public const string LobbyArenaPrefabPath =
            "Assets/MazeParty/Prefabs/Multiplayer/World/LobbyArena.prefab";
        public const string GrenadeRangeIndicatorPrefabPath =
            "Assets/MazeParty/Prefabs/Board/UI/GrenadeRangeIndicator.prefab";

        private const string BootstrapScenePath =
            "Assets/MazeParty/Scenes/Multiplayer/OnlineBootstrap.unity";
        private const string PlayerAssetFolder =
            "Assets/MazeParty/Prefabs/Multiplayer/Player";
        private const string BodyMaterialPath =
            PlayerAssetFolder + "/PlayerBody.mat";
        private const string FeatureMaterialPath =
            PlayerAssetFolder + "/PlayerFeature.mat";
        private const string HighlightMaterialPath =
            PlayerAssetFolder + "/PlayerHighlight.mat";
        private const string LobbyFloorMaterialPath =
            "Assets/MazeParty/Board/Materials/RoomNormalA.mat";
        private const string LobbyWallMaterialPath =
            "Assets/MazeParty/Board/Materials/RoomNormalB.mat";
        private const string GrenadeRangeIndicatorMaterialPath =
