        private static PlayerAvatarPresentationBindings
            EnsurePlayerPresentationAssets()
        {
            EnsureFolder(PlayerAssetFolder);
            EnsureFolder("Assets/MazeParty/Resources/MazeParty/Player");

            var waterShield = SharedVfxProjectSetup
                .EnsureWaterShieldPrefab();
            var worldIndicator = EnsurePlayerWorldIndicatorPrefab(
                waterShield);

            var prefab = AssetDatabase.LoadAssetAtPath<GameObject>(
                PlayerPresentationPrefabPath);
            if (prefab == null)
            {
                if (AssetDatabase.LoadMainAssetAtPath(
                        PlayerPresentationPrefabPath) != null)
                {
                    throw new InvalidOperationException(
                        "An incompatible asset exists at " +
                        PlayerPresentationPrefabPath + ".");
                }
                var template = CreatePlayerPresentationTemplate(
                    waterShield);
                try
                {
                    prefab = PrefabUtility.SaveAsPrefabAsset(
                        template,
                        PlayerPresentationPrefabPath);
                }
                finally
                {
                    Object.DestroyImmediate(template);
                }
            }
            else
            {
                RepairPresentationHitZoneScripts();
                UpgradePlayerPresentationLobbyNameplate();
                UpgradePlayerPresentationShieldVfx(waterShield);
                UpgradePlayerPresentationHandEmoteRotations();
                prefab = AssetDatabase.LoadAssetAtPath<GameObject>(
                    PlayerPresentationPrefabPath);
            }

            var bindings = prefab != null
                ? prefab.GetComponent<PlayerAvatarPresentationBindings>()
                : null;
            if (bindings == null || !bindings.HasRequiredReferences)
            {
                throw new InvalidOperationException(
                    "PlayerAvatarPresentation.prefab has incomplete bindings. " +
                    "Repair the prefab instead of recreating it.");
            }
            ValidateShieldVfxInstance(bindings.ShieldVfx);
            ValidateHitZone(bindings.BodyHitbox, PlayerHitRegion.Body);
            ValidateHitZone(bindings.HeadHitbox, PlayerHitRegion.Head);
            ValidateHitZone(bindings.LeftHandHitbox, PlayerHitRegion.Hand);
            ValidateHitZone(bindings.RightHandHitbox, PlayerHitRegion.Hand);

            var assets = AssetDatabase.LoadAssetAtPath<
                PlayerAvatarPresentationAssets>(PlayerPresentationAssetsPath);
            if (assets == null)
            {
                assets = ScriptableObject.CreateInstance<
                    PlayerAvatarPresentationAssets>();
                assets.Configure(bindings, worldIndicator);
                AssetDatabase.CreateAsset(assets, PlayerPresentationAssetsPath);
            }
            else if (assets.PresentationPrefab == null ||
                     assets.WorldIndicatorPrefab == null)
            {
                assets.Configure(bindings, worldIndicator);
                EditorUtility.SetDirty(assets);
            }
            if (!assets.HasRequiredReferences)
            {
                throw new InvalidOperationException(
                    "PlayerAvatarPresentationAssets has incomplete references.");
            }
            return bindings;
        }

        private static PlayerWorldIndicator EnsurePlayerWorldIndicatorPrefab(
            GameObject waterShield)
        {
            var prefab = AssetDatabase.LoadAssetAtPath<GameObject>(
                PlayerWorldIndicatorPrefabPath);
            if (prefab == null)
            {
                if (AssetDatabase.LoadMainAssetAtPath(
                        PlayerWorldIndicatorPrefabPath) != null)
                {
                    throw new InvalidOperationException(
                        "An incompatible asset exists at " +
                        PlayerWorldIndicatorPrefabPath + ".");
                }

                var template = CreatePlayerWorldIndicatorTemplate(
                    waterShield);
                try
                {
                    prefab = PrefabUtility.SaveAsPrefabAsset(
                        template,
                        PlayerWorldIndicatorPrefabPath);
                }
                finally
                {
                    Object.DestroyImmediate(template);
                }
            }
            else
            {
                UpgradePlayerWorldIndicatorShieldVfx(waterShield);
                prefab = AssetDatabase.LoadAssetAtPath<GameObject>(
                    PlayerWorldIndicatorPrefabPath);
            }

            var indicator = prefab != null
                ? prefab.GetComponent<PlayerWorldIndicator>()
                : null;
            if (indicator == null || !indicator.HasRequiredReferences)
            {
                throw new InvalidOperationException(
                    "PlayerWorldIndicator.prefab has incomplete bindings. " +
                    "Repair the prefab instead of recreating it.");
            }
            ValidateShieldVfxInstance(indicator.LocalStartHighlight);

            return indicator;
        }

        private static BoardGrenadeRangeIndicator
            EnsureGrenadeRangeIndicatorPrefab()
        {
            EnsureFolder("Assets/MazeParty/Prefabs/Board/UI");
            EnsureFolder("Assets/MazeParty/Board/Materials");
            var material = EnsureMaterial(
                GrenadeRangeIndicatorMaterialPath,
                new Color(1f, 0.42f, 0.1f),
                0.05f);
            var prefab = AssetDatabase.LoadAssetAtPath<GameObject>(
                GrenadeRangeIndicatorPrefabPath);
            if (prefab == null)
            {
                if (AssetDatabase.LoadMainAssetAtPath(
                        GrenadeRangeIndicatorPrefabPath) != null)
                {
                    throw new InvalidOperationException(
                        "An incompatible asset exists at " +
                        GrenadeRangeIndicatorPrefabPath + ".");
                }

                var template = CreateGrenadeRangeIndicatorTemplate(material);
                try
                {
                    prefab = PrefabUtility.SaveAsPrefabAsset(
                        template,
                        GrenadeRangeIndicatorPrefabPath);
                }
                finally
                {
                    Object.DestroyImmediate(template);
                }
            }
            var indicator = prefab != null
                ? prefab.GetComponent<BoardGrenadeRangeIndicator>()
                : null;
            if (indicator == null ||
                !indicator.HasRequiredReferences ||
                indicator.IsVisible ||
                prefab.GetComponentsInChildren<Collider>(true).Length != 0 ||
                prefab.GetComponentsInChildren<NetworkObject>(true).Length != 0)
            {
                throw new InvalidOperationException(
                    "GrenadeRangeIndicator.prefab has incomplete authored " +
                    "bindings. Repair the prefab instead of recreating it.");
            }

            return indicator;
        }

        private static GameObject CreateGrenadeRangeIndicatorTemplate(
            Material material)
        {
            const int segmentCount = 64;
            var root = new GameObject(
                "GrenadeRangeIndicator",
                typeof(BoardGrenadeRangeIndicator));
            var ring = new GameObject("Range Ring", typeof(LineRenderer));
            ring.transform.SetParent(root.transform, false);
            // The player root is authored at capsule-center height. Offset the
            // range ring to the standing foot plane, then keep a small lift to
            // prevent z-fighting with the board surface.
            ring.transform.localPosition = new Vector3(0f, -0.94f, 0f);

            var line = ring.GetComponent<LineRenderer>();
            line.useWorldSpace = false;
            line.loop = true;
            line.positionCount = segmentCount;
            line.widthMultiplier = 0.08f;
            line.numCornerVertices = 2;
            line.numCapVertices = 2;
            line.alignment = LineAlignment.View;
            line.textureMode = LineTextureMode.Stretch;
            line.sharedMaterial = material;
            line.shadowCastingMode = ShadowCastingMode.Off;
            line.receiveShadows = false;
            line.lightProbeUsage = LightProbeUsage.Off;
            line.reflectionProbeUsage = ReflectionProbeUsage.Off;
            for (var index = 0; index < segmentCount; index++)
            {
                var radians = index * Mathf.PI * 2f / segmentCount;
                line.SetPosition(
                    index,
                    new Vector3(Mathf.Cos(radians), 0f, Mathf.Sin(radians)));
            }

            root.GetComponent<BoardGrenadeRangeIndicator>().Configure(
                ring,
                ring.transform,
                line);
            ring.SetActive(false);
            return root;
        }

        /// <summary>
        /// Repairs only the four hit-zone components written with a null
        /// MonoScript reference by the original multi-type PlayerHitZones.cs.
        /// Any additional missing script aborts the migration so unrelated
        /// authored data is never removed implicitly.
        /// </summary>
        private static void RepairPresentationHitZoneScripts()
        {
            var root = PrefabUtility.LoadPrefabContents(
                PlayerPresentationPrefabPath);
            try
            {
                var bindings = root.GetComponent<
                    PlayerAvatarPresentationBindings>();
                if (bindings == null)
                {
                    throw new InvalidOperationException(
                        "PlayerAvatarPresentation.prefab has no bindings component.");
                }

                var hitboxObjects = new[]
                {
                    RequireHitboxObject(bindings.BodyHitbox, "BodyHitbox"),
                    RequireHitboxObject(bindings.HeadHitbox, "HeadHitbox"),
                    RequireHitboxObject(bindings.LeftHandHitbox, "LeftHandHitbox"),
                    RequireHitboxObject(bindings.RightHandHitbox, "RightHandHitbox")
                };

                foreach (var child in root.GetComponentsInChildren<Transform>(true))
                {
                    var missingCount = GameObjectUtility
                        .GetMonoBehavioursWithMissingScriptCount(child.gameObject);
                    if (missingCount == 0)
                    {
                        continue;
                    }

                    var hitboxIndex = Array.IndexOf(hitboxObjects, child.gameObject);
                    var hasValidZone = child.GetComponent<PlayerHitZone>() != null;
                    if (hitboxIndex < 0 || missingCount != 1 || hasValidZone)
                    {
                        throw new InvalidOperationException(
                            "Unexpected missing script on '" +
                            GetHierarchyPath(child, root.transform) +
                            "'. The installer will not remove authored components " +
                            "outside the four known hit-zone migration targets.");
                    }
                }

                var changed = false;
                changed |= RepairHitZone(
                    hitboxObjects[0],
                    PlayerHitRegion.Body);
                changed |= RepairHitZone(
                    hitboxObjects[1],
                    PlayerHitRegion.Head);
                changed |= RepairHitZone(
                    hitboxObjects[2],
                    PlayerHitRegion.Hand);
                changed |= RepairHitZone(
                    hitboxObjects[3],
                    PlayerHitRegion.Hand);

                if (changed)
                {
                    PrefabUtility.SaveAsPrefabAsset(
                        root,
                        PlayerPresentationPrefabPath);
                }
            }
            finally
            {
                PrefabUtility.UnloadPrefabContents(root);
            }
        }

        private static GameObject RequireHitboxObject(
            Collider collider,
            string expectedName)
        {
            if (collider == null || collider.gameObject.name != expectedName)
            {
                throw new InvalidOperationException(
                    "PlayerAvatarPresentation.prefab is missing the authored '" +
                    expectedName + "' collider binding.");
            }
            return collider.gameObject;
        }

        private static void UpgradePlayerPresentationLobbyNameplate()
        {
            var root = PrefabUtility.LoadPrefabContents(
                PlayerPresentationPrefabPath);
            try
            {
                var bindings = root.GetComponent<
                    PlayerAvatarPresentationBindings>();
                if (bindings == null || bindings.NameplateAnchor == null)
                {
                    throw new InvalidOperationException(
                        "PlayerAvatarPresentation.prefab has no authored nameplate binding.");
                }

                var changed = false;
                var hostIcon = bindings.LobbyHostIcon;
                if (hostIcon == null)
                {
                    var existing = bindings.NameplateAnchor.Find(
                        "Lobby Host Icon");
                    hostIcon = existing != null
                        ? existing.GetComponent<SpriteRenderer>()
                        : null;
                    if (existing != null && hostIcon == null)
                    {
                        throw new InvalidOperationException(
                            "The authored Lobby Host Icon has no SpriteRenderer.");
                    }

                    if (hostIcon == null)
                    {
                        hostIcon = CreateLobbyHostIcon(
                            bindings.NameplateAnchor);
                    }

                    var serializedBindings = new SerializedObject(bindings);
                    serializedBindings.FindProperty("lobbyHostIcon")
                        .objectReferenceValue = hostIcon;
                    var readyColor = serializedBindings.FindProperty(
                        "lobbyReadyNameColor");
                    if (readyColor.colorValue.g <= readyColor.colorValue.r ||
                        readyColor.colorValue.g <= readyColor.colorValue.b)
                    {
                        readyColor.colorValue =
                            new Color32(88, 220, 112, 255);
                    }
                    serializedBindings.ApplyModifiedPropertiesWithoutUndo();
                    changed = true;
                }

                if (hostIcon.transform.parent != bindings.NameplateAnchor)
                {
                    throw new InvalidOperationException(
                        "The lobby host icon must remain directly under NameplateAnchor.");
                }

                var starSprite = AssetDatabase.LoadAssetAtPath<Sprite>(
                    HostStarSpritePath);
                if (starSprite == null)
                {
                    throw new InvalidOperationException(
                        "Modern UI host star is missing at " +
                        HostStarSpritePath + ".");
                }
                if (hostIcon.sprite == null)
                {
                    hostIcon.sprite = starSprite;
                    changed = true;
                }
                if (hostIcon.gameObject.activeSelf)
                {
                    hostIcon.gameObject.SetActive(false);
                    changed = true;
                }

                if (changed)
                {
                    PrefabUtility.SaveAsPrefabAsset(
                        root,
                        PlayerPresentationPrefabPath);
                }
            }
            finally
            {
                PrefabUtility.UnloadPrefabContents(root);
            }
        }

        private static void UpgradePlayerPresentationShieldVfx(
            GameObject waterShield)
        {
            var root = PrefabUtility.LoadPrefabContents(
                PlayerPresentationPrefabPath);
            try
            {
                var bindings = root.GetComponent<
                    PlayerAvatarPresentationBindings>();
                if (bindings == null)
                {
                    throw new InvalidOperationException(
                        "PlayerAvatarPresentation.prefab has no bindings.");
                }

                var changed = false;
                var shieldVfx = bindings.ShieldVfx;
                if (shieldVfx == null)
                {
                    var existing = root.transform.Find("Water Shield VFX");
                    shieldVfx = existing != null
                        ? existing.gameObject
                        : CreateShieldVfx(root.transform, waterShield);
                    var serialized = new SerializedObject(bindings);
                    var property = serialized.FindProperty("shieldVfx");
                    if (property == null)
                    {
                        throw new InvalidOperationException(
                            "PlayerAvatarPresentationBindings has no " +
                            "shield VFX field. Wait for scripts to compile " +
                            "and retry.");
                    }
                    property.objectReferenceValue = shieldVfx;
                    serialized.ApplyModifiedPropertiesWithoutUndo();
                    changed = true;
                }

                ValidateShieldVfxInstance(shieldVfx);
                if (shieldVfx.activeSelf)
                {
                    shieldVfx.SetActive(false);
                    changed = true;
                }

                if (changed)
                {
                    PrefabUtility.SaveAsPrefabAsset(
                        root,
                        PlayerPresentationPrefabPath);
                }
            }
            finally
            {
                PrefabUtility.UnloadPrefabContents(root);
            }
        }

        private static void UpgradePlayerPresentationHandEmoteRotations()
        {
            var root = PrefabUtility.LoadPrefabContents(
                PlayerPresentationPrefabPath);
            try
            {
                var bindings = root.GetComponent<
                    PlayerAvatarPresentationBindings>();
                if (bindings == null)
                {
                    throw new InvalidOperationException(
                        "PlayerAvatarPresentation.prefab has no bindings.");
                }

                if (!bindings.EnsureHandEmoteRotationSettings())
                {
                    return;
                }
                EditorUtility.SetDirty(bindings);
                PrefabUtility.SaveAsPrefabAsset(
                    root,
                    PlayerPresentationPrefabPath);
            }
            finally
            {
                PrefabUtility.UnloadPrefabContents(root);
            }
        }

        private static void UpgradePlayerWorldIndicatorShieldVfx(
            GameObject waterShield)
        {
            var root = PrefabUtility.LoadPrefabContents(
                PlayerWorldIndicatorPrefabPath);
            try
            {
                var indicator = root.GetComponent<PlayerWorldIndicator>();
                if (indicator == null)
                {
                    throw new InvalidOperationException(
                        "PlayerWorldIndicator.prefab has no bindings.");
                }

                var changed = false;
                var previousHighlight = indicator.LocalStartHighlight;
                var shieldVfx = previousHighlight;
                if (!IsShieldVfxInstance(shieldVfx))
                {
                    var existing = root.transform.Find("Water Shield VFX");
                    shieldVfx = existing != null &&
                                IsShieldVfxInstance(existing.gameObject)
                        ? existing.gameObject
                        : CreateShieldVfx(root.transform, waterShield);

                    var serialized = new SerializedObject(indicator);
                    var property = serialized.FindProperty(
                        "localStartHighlight");
                    if (property == null)
                    {
                        throw new InvalidOperationException(
                            "PlayerWorldIndicator has no local location " +
                            "highlight field. Wait for scripts to compile " +
                            "and retry.");
                    }
                    property.objectReferenceValue = shieldVfx;
                    serialized.ApplyModifiedPropertiesWithoutUndo();
                    if (previousHighlight != null &&
                        previousHighlight != shieldVfx &&
                        previousHighlight.name ==
                            "Local Player Start Highlight")
                    {
                        Object.DestroyImmediate(previousHighlight);
                    }
                    changed = true;
                }

                ValidateShieldVfxInstance(shieldVfx);
                if (shieldVfx.activeSelf)
                {
                    shieldVfx.SetActive(false);
                    changed = true;
                }

                if (changed)
                {
                    PrefabUtility.SaveAsPrefabAsset(
                        root,
                        PlayerWorldIndicatorPrefabPath);
                }
            }
            finally
            {
                PrefabUtility.UnloadPrefabContents(root);
            }
        }

        private static SpriteRenderer CreateLobbyHostIcon(Transform nameplate)
        {
            var starSprite = AssetDatabase.LoadAssetAtPath<Sprite>(
                HostStarSpritePath);
            if (starSprite == null)
            {
                throw new InvalidOperationException(
                    "Modern UI host star is missing at " +
                    HostStarSpritePath + ".");
            }

            var iconObject = new GameObject(
                "Lobby Host Icon",
                typeof(SpriteRenderer));
            iconObject.transform.SetParent(nameplate, false);
            iconObject.transform.localPosition = new Vector3(-0.95f, 0f, 0f);
            iconObject.transform.localScale = Vector3.one * 0.28f;
            var hostIcon = iconObject.GetComponent<SpriteRenderer>();
            hostIcon.sprite = starSprite;
            hostIcon.color = new Color32(255, 214, 86, 255);
            hostIcon.sortingOrder = 1;
            hostIcon.shadowCastingMode = ShadowCastingMode.Off;
            hostIcon.receiveShadows = false;
            iconObject.SetActive(false);
            return hostIcon;
        }

        private static bool RepairHitZone(
            GameObject hitbox,
            PlayerHitRegion expectedRegion)
        {
            var missingCount = GameObjectUtility
                .GetMonoBehavioursWithMissingScriptCount(hitbox);
            var zone = hitbox.GetComponent<PlayerHitZone>();
            if (missingCount == 0)
            {
                if (zone == null)
                {
                    throw new InvalidOperationException(
                        "Authored hitbox '" + hitbox.name +
                        "' has no PlayerHitZone component.");
                }
                if (zone.Region == expectedRegion)
                {
                    return false;
                }

                zone.Configure(expectedRegion);
                EditorUtility.SetDirty(zone);
                return true;
            }

            if (missingCount != 1 || zone != null)
            {
                throw new InvalidOperationException(
                    "Authored hitbox '" + hitbox.name +
                    "' has an unexpected missing-script layout.");
            }

            GameObjectUtility.RemoveMonoBehavioursWithMissingScript(hitbox);
            hitbox.AddComponent<PlayerHitZone>().Configure(expectedRegion);
            return true;
        }

        private static void ValidateHitZone(
            Collider collider,
            PlayerHitRegion expectedRegion)
        {
            var zone = collider != null
                ? collider.GetComponent<PlayerHitZone>()
                : null;
            if (zone == null || zone.Region != expectedRegion ||
                GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(
                    collider.gameObject) != 0)
            {
                throw new InvalidOperationException(
                    "PlayerAvatarPresentation.prefab has an incomplete '" +
                    (collider != null ? collider.gameObject.name : "hitbox") +
                    "' hit-zone contract.");
            }
        }

        private static string GetHierarchyPath(
            Transform target,
            Transform root)
        {
            var path = target.name;
            while (target.parent != null && target.parent != root.parent)
            {
                target = target.parent;
                path = target.name + "/" + path;
            }
            return path;
        }

        private static GameObject CreatePlayerPresentationTemplate(
            GameObject waterShield)
        {
            var bodyMaterial = EnsureMaterial(
                BodyMaterialPath,
                new Color(0.95f, 0.25f, 0.25f),
                0.22f);
            var featureMaterial = EnsureMaterial(
                FeatureMaterialPath,
                new Color(0.025f, 0.02f, 0.02f),
                0.12f);
            var highlightMaterial = EnsureMaterial(
                HighlightMaterialPath,
                Color.white,
                0.05f);

            var root = new GameObject(
                "VisualRoot",
                typeof(PlayerAvatarPresentationBindings));
            var world = CreateAnchor(root.transform, "WorldModel");
            var body = CreatePosePart(
                world,
                "BodyAnchor",
                PrimitiveType.Capsule,
                bodyMaterial,
