        private static void MigrateNetworkPlayerPrefab(
            PlayerAvatarPresentationBindings presentationPrefab,
            BoardGrenadeRangeIndicator grenadeRangeIndicatorPrefab)
        {
            var root = PrefabUtility.LoadPrefabContents(PlayerPrefabPath);
            try
            {
                var changed = false;
                var visual = root.GetComponent<PlayerAvatarVisual>();
                var networkAvatar = root.GetComponent<NetworkPlayerAvatar>();
                if (visual == null || networkAvatar == null)
                {
                    throw new InvalidOperationException(
                        "NetworkPlayer.prefab is missing required runtime components.");
                }

                var controller = root.GetComponent<CharacterController>();
                if (controller == null)
                {
                    throw new InvalidOperationException(
                        "NetworkPlayer.prefab is missing its root CharacterController.");
                }
                if (!Mathf.Approximately(
                        controller.radius,
                        PlayerAvatarVisual.MovementControllerRadius))
                {
                    controller.radius =
                        PlayerAvatarVisual.MovementControllerRadius;
                    changed = true;
                }

                var bindings = root.GetComponentInChildren<
                    PlayerAvatarPresentationBindings>(true);
                if (bindings == null)
                {
                    var instance = (GameObject)PrefabUtility.InstantiatePrefab(
                        presentationPrefab.gameObject,
                        root.transform);
                    instance.name = presentationPrefab.gameObject.name;
                    bindings = instance.GetComponent<
                        PlayerAvatarPresentationBindings>();
                    changed = true;
                }
                if (visual.Bindings != bindings)
                {
                    visual.ConfigurePresentationBindings(bindings);
                    changed = true;
                }

                var grenadeRangeIndicator = root.GetComponentInChildren<
                    BoardGrenadeRangeIndicator>(true);
                if (grenadeRangeIndicator == null)
                {
                    var instance = (GameObject)PrefabUtility.InstantiatePrefab(
                        grenadeRangeIndicatorPrefab.gameObject,
                        root.transform);
                    instance.name =
                        grenadeRangeIndicatorPrefab.gameObject.name;
                    grenadeRangeIndicator = instance.GetComponent<
                        BoardGrenadeRangeIndicator>();
                    changed = true;
                }

                var eyePivot = root.transform.Find("CameraPivot");
                if (eyePivot == null)
                {
                    eyePivot = new GameObject("CameraPivot").transform;
                    eyePivot.SetParent(root.transform, false);
                    eyePivot.localPosition = new Vector3(0f, 0.75f, 0f);
                    changed = true;
                }
                var avatarObject = new SerializedObject(networkAvatar);
                var eyeProperty = avatarObject.FindProperty("eyePivot");
                if (eyeProperty.objectReferenceValue != eyePivot)
                {
                    eyeProperty.objectReferenceValue = eyePivot;
                    changed = true;
                }
                var grenadeRangeProperty = avatarObject.FindProperty(
                    "grenadeRangeIndicator");
                if (grenadeRangeProperty == null)
                {
                    throw new InvalidOperationException(
                        "NetworkPlayerAvatar is missing the serialized " +
                        "grenade range indicator binding.");
                }
                if (grenadeRangeProperty.objectReferenceValue !=
                    grenadeRangeIndicator)
                {
                    grenadeRangeProperty.objectReferenceValue =
                        grenadeRangeIndicator;
                    changed = true;
                }
                avatarObject.ApplyModifiedPropertiesWithoutUndo();
                if (root.GetComponent<PlayerHitZoneOwner>() == null)
                {
                    root.AddComponent<PlayerHitZoneOwner>();
                    changed = true;
                }

                if (changed)
                {
                    PrefabUtility.SaveAsPrefabAsset(root, PlayerPrefabPath);
                }
            }
            finally
            {
                PrefabUtility.UnloadPrefabContents(root);
            }
        }

        private static GameObject CreateNetworkPlayerTemplate(
            PlayerAvatarPresentationBindings presentationPrefab,
            BoardGrenadeRangeIndicator grenadeRangeIndicatorPrefab)
        {
            var root = new GameObject("NetworkPlayer");
            var controller = root.AddComponent<CharacterController>();
            controller.height = 2f;
            controller.radius = PlayerAvatarVisual.MovementControllerRadius;
            controller.center = Vector3.zero;
            root.AddComponent<NetworkObject>();
            var networkTransform = root.AddComponent<NetworkTransform>();
            networkTransform.Interpolate = true;
            networkTransform.SyncScaleX = false;
            networkTransform.SyncScaleY = false;
            networkTransform.SyncScaleZ = false;

            var presentation = (GameObject)PrefabUtility.InstantiatePrefab(
                presentationPrefab.gameObject,
                root.transform);
            presentation.name = presentationPrefab.gameObject.name;
            var visual = root.AddComponent<PlayerAvatarVisual>();
            visual.ConfigurePresentationBindings(
                presentation.GetComponent<PlayerAvatarPresentationBindings>());
            root.AddComponent<PlayerHitZoneOwner>();
            var eyePivot = new GameObject("CameraPivot").transform;
            eyePivot.SetParent(root.transform, false);
            eyePivot.localPosition = new Vector3(0f, 0.75f, 0f);
            var networkAvatar = root.AddComponent<NetworkPlayerAvatar>();
            var grenadeRangeInstance =
                (GameObject)PrefabUtility.InstantiatePrefab(
                    grenadeRangeIndicatorPrefab.gameObject,
                    root.transform);
            grenadeRangeInstance.name =
                grenadeRangeIndicatorPrefab.gameObject.name;
            var grenadeRangeIndicator = grenadeRangeInstance.GetComponent<
                BoardGrenadeRangeIndicator>();
            var avatarObject = new SerializedObject(networkAvatar);
            avatarObject.FindProperty("eyePivot").objectReferenceValue = eyePivot;
            avatarObject.FindProperty("grenadeRangeIndicator")
                .objectReferenceValue = grenadeRangeIndicator;
            avatarObject.ApplyModifiedPropertiesWithoutUndo();
            var walls = root.AddComponent<PlayerBoardBoundaryWalls>();
            walls.ConfigureWorldPrefabs(BoardWorldPrefabProjectSetup.EnsureAssets());
            return root;
        }

        private static GameObject CreateLobbyArenaTemplate()
        {
            var floorMaterial = LoadRequiredMaterial(LobbyFloorMaterialPath);
            var wallMaterial = LoadRequiredMaterial(LobbyWallMaterialPath);
            var root = new GameObject(
                "LobbyArena",
                typeof(LobbyArena),
                typeof(LobbyArenaBindings));
            var presentation = new GameObject("Presentation");
            presentation.transform.SetParent(root.transform, false);
            CreateLobbyPart(
                "Floor",
                presentation.transform,
                new Vector3(0f, -0.25f, 0f),
                new Vector3(13f, 0.5f, 9f),
                floorMaterial);
            CreateLobbyPart(
                "North Wall",
                presentation.transform,
                new Vector3(0f, 0.4f, 4.25f),
                new Vector3(13f, 0.8f, 0.5f),
                wallMaterial);
            CreateLobbyPart(
                "South Wall",
                presentation.transform,
                new Vector3(0f, 0.4f, -4.25f),
                new Vector3(13f, 0.8f, 0.5f),
                wallMaterial);
            CreateLobbyPart(
                "East Wall",
                presentation.transform,
                new Vector3(6.25f, 0.4f, 0f),
                new Vector3(0.5f, 0.8f, 8f),
                wallMaterial);
            CreateLobbyPart(
                "West Wall",
                presentation.transform,
                new Vector3(-6.25f, 0.4f, 0f),
                new Vector3(0.5f, 0.8f, 8f),
                wallMaterial);

            var boundsObject = new GameObject(
                "Horizontal Bounds",
                typeof(BoxCollider));
            boundsObject.transform.SetParent(root.transform, false);
            var bounds = boundsObject.GetComponent<BoxCollider>();
            bounds.size = new Vector3(12f, 2f, 8f);
            bounds.enabled = false;

            var spawnRoot = new GameObject("Spawn Anchors").transform;
            spawnRoot.SetParent(root.transform, false);
            var positions = new[]
            {
                new Vector3(-2.7f, 1f, -1.8f),
                new Vector3(2.7f, 1f, -1.8f),
                new Vector3(-2.7f, 1f, 1.8f),
                new Vector3(2.7f, 1f, 1.8f)
            };
            var spawns = new Transform[positions.Length];
            for (var index = 0; index < positions.Length; index++)
            {
                spawns[index] = CreateAnchor(
                    spawnRoot,
                    "Player Spawn " + (index + 1));
                spawns[index].localPosition = positions[index];
            }

            var bindings = root.GetComponent<LobbyArenaBindings>();
            bindings.Configure(presentation, bounds, spawns);
            root.GetComponent<LobbyArena>().ConfigureBindings(bindings);
            return root;
        }

        private static void InstallLobbySceneInstance()
        {
            var prefab = LoadOrCreateLobbyArenaPrefab();
            var scene = EditorSceneManager.OpenScene(
                BootstrapScenePath,
                OpenSceneMode.Single);
            var arenas = scene.GetRootGameObjects()
                .SelectMany(root =>
                    root.GetComponentsInChildren<LobbyArena>(true))
                .ToArray();
            if (arenas.Length > 1)
            {
                throw new InvalidOperationException(
                    "OnlineBootstrap contains multiple LobbyArena instances.");
            }
            if (arenas.Length == 1 &&
                PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(
                    arenas[0].gameObject) == LobbyArenaPrefabPath &&
                arenas[0].HasRequiredReferences)
            {
                return;
            }

            var position = arenas.Length == 1
                ? arenas[0].RoomCenter
                : new Vector3(3.5f, 0f, 0f);
            if (arenas.Length == 1)
            {
                Object.DestroyImmediate(arenas[0].gameObject);
            }
            var instance = (GameObject)PrefabUtility.InstantiatePrefab(
                prefab,
                scene);
            instance.transform.position = position;
            EditorSceneManager.MarkSceneDirty(scene);
            EditorSceneManager.SaveScene(scene);
        }

        private static void ValidateNetworkPlayerPrefab(GameObject prefab)
        {
            var visual = prefab != null
                ? prefab.GetComponent<PlayerAvatarVisual>()
                : null;
            var avatar = prefab != null
                ? prefab.GetComponent<NetworkPlayerAvatar>()
                : null;
            var grenadeRangeIndicators = prefab != null
                ? prefab.GetComponentsInChildren<
                    BoardGrenadeRangeIndicator>(true)
                : Array.Empty<BoardGrenadeRangeIndicator>();
            var grenadeRangeIndicator = grenadeRangeIndicators.Length == 1
                ? grenadeRangeIndicators[0]
                : null;
            var avatarObject = avatar != null
                ? new SerializedObject(avatar)
                : null;
            var grenadeRangeProperty = avatarObject?.FindProperty(
                "grenadeRangeIndicator");
            var controller = prefab != null
                ? prefab.GetComponent<CharacterController>()
                : null;
            var movementControllers = prefab != null
                ? prefab.GetComponentsInChildren<CharacterController>(true)
                : Array.Empty<CharacterController>();
            var nonMovementColliders = prefab != null
                ? prefab.GetComponentsInChildren<Collider>(true)
                    .Where(collider => collider != controller)
                    .ToArray()
                : Array.Empty<Collider>();
            if (prefab == null ||
                prefab.GetComponent<NetworkObject>() == null ||
                prefab.GetComponent<NetworkTransform>() == null ||
                controller == null ||
                movementControllers.Length != 1 ||
                movementControllers[0] != controller ||
                !controller.enabled ||
                !Mathf.Approximately(
                    controller.radius,
                    PlayerAvatarVisual.MovementControllerRadius) ||
                nonMovementColliders.Length != 4 ||
                nonMovementColliders.Any(collider =>
                    !collider.isTrigger ||
                    collider.GetComponent<PlayerHitZone>() == null) ||
                prefab.GetComponent<PlayerHitZoneOwner>() == null ||
                prefab.GetComponent<PlayerBoardBoundaryWalls>() == null ||
                visual == null || visual.Bindings == null ||
                !visual.Bindings.HasRequiredReferences ||
                avatar == null || prefab.transform.Find("CameraPivot") == null ||
                grenadeRangeIndicator == null ||
                !grenadeRangeIndicator.HasRequiredReferences ||
                grenadeRangeIndicator.IsVisible ||
                grenadeRangeIndicator.GetComponentsInChildren<Collider>(true)
                    .Length != 0 ||
                grenadeRangeIndicator.GetComponentsInChildren<NetworkObject>(true)
                    .Length != 0 ||
                PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(
                    grenadeRangeIndicator.gameObject) !=
                    GrenadeRangeIndicatorPrefabPath ||
                grenadeRangeProperty == null ||
                grenadeRangeProperty.objectReferenceValue !=
                    grenadeRangeIndicator)
            {
                throw new InvalidOperationException(
                    "NetworkPlayer.prefab has incomplete authored contracts.");
            }
        }

        private static void ValidateLobbyArenaPrefab(GameObject prefab)
        {
            var arena = prefab != null ? prefab.GetComponent<LobbyArena>() : null;
            if (arena == null || !arena.HasRequiredReferences ||
                arena.SpawnCount != MultiplayerConstants.MaxPlayers)
            {
                throw new InvalidOperationException(
                    "LobbyArena.prefab has incomplete authored bindings.");
            }
        }

        private static Material EnsureMaterial(
            string path,
            Color color,
            float smoothness)
        {
            var material = AssetDatabase.LoadAssetAtPath<Material>(path);
            if (material != null)
            {
                return material;
            }
            material = WorldTextOcclusion.CreateBuildSafeLitMaterial(
                System.IO.Path.GetFileNameWithoutExtension(path));
            if (material == null)
            {
                throw new InvalidOperationException(
                    "A build-safe Lit shader is required for player presentation.");
            }
            material.SetColor("_BaseColor", color);
            material.SetColor("_Color", color);
            material.SetFloat("_Metallic", 0f);
            material.SetFloat("_Smoothness", smoothness);
            AssetDatabase.CreateAsset(material, path);
            return material;
        }

        private static Material LoadRequiredMaterial(string path)
        {
            var material = AssetDatabase.LoadAssetAtPath<Material>(path);
            if (material == null)
            {
                throw new InvalidOperationException(
                    "Required material is missing: " + path);
            }
            return material;
        }

        private static Transform CreateAnchor(Transform parent, string name)
        {
            var anchor = new GameObject(name).transform;
            anchor.SetParent(parent, false);
            return anchor;
        }

        private static Transform CreatePosePart(
            Transform parent,
            string name,
            PrimitiveType primitive,
            Material material,
            out Renderer renderer)
        {
            var anchor = CreateAnchor(parent, name);
            var visual = CreatePrimitive(
                name + " Visual",
                primitive,
                anchor,
                material);
            renderer = visual.GetComponent<Renderer>();
            return anchor;
        }

        private static GameObject CreatePrimitive(
            string name,
            PrimitiveType primitive,
            Transform parent,
            Material material)
        {
            var value = GameObject.CreatePrimitive(primitive);
            value.name = name;
            value.transform.SetParent(parent, false);
            var collider = value.GetComponent<Collider>();
            if (collider != null)
            {
                Object.DestroyImmediate(collider);
            }
            var renderer = value.GetComponent<Renderer>();
            renderer.sharedMaterial = material;
            return value;
        }

        private static T CreateHitbox<T>(
            Transform parent,
            string name,
            PlayerHitRegion region)
            where T : Collider
        {
            var value = new GameObject(name);
            value.transform.SetParent(parent, false);
            value.AddComponent<PlayerHitZone>().Configure(region);
            var collider = value.AddComponent<T>();
            collider.isTrigger = true;
            return collider;
        }

        private static GameObject CreateShieldVfx(
            Transform parent,
            GameObject waterShield)
        {
            if (waterShield == null)
            {
                throw new InvalidOperationException(
                    "The shared Water Shield wrapper is required.");
            }

            var instance = PrefabUtility.InstantiatePrefab(
                waterShield,
                parent) as GameObject;
            if (instance == null)
            {
                throw new InvalidOperationException(
                    "Could not instantiate the shared Water Shield wrapper.");
            }

            instance.name = "Water Shield VFX";
            instance.transform.localPosition = Vector3.zero;
            instance.transform.localRotation = Quaternion.identity;
            instance.transform.localScale = Vector3.one;
            instance.SetActive(false);
            return instance;
        }

        private static bool IsShieldVfxInstance(GameObject candidate)
        {
            return candidate != null && string.Equals(
                PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(
                    candidate),
                SharedVfxProjectSetup.WaterShieldPrefabPath,
                StringComparison.OrdinalIgnoreCase);
        }

        private static void ValidateShieldVfxInstance(GameObject candidate)
        {
            if (!IsShieldVfxInstance(candidate) ||
                candidate.GetComponentsInChildren<Collider>(true).Length > 0 ||
                candidate.GetComponentsInChildren<NetworkObject>(true).Length > 0)
            {
                throw new InvalidOperationException(
                    "Player presentation shield must use the shared, " +
                    "presentation-only WaterShield.prefab wrapper.");
            }
        }

        private static GameObject CreateHighlight(
            Transform parent,
            Material material)
        {
            var root = new GameObject("Local Player Top View Highlight");
            root.transform.SetParent(parent, false);
            root.transform.localPosition = new Vector3(0f, -0.98f, 0f);
            const float extent = 0.72f;
            const float width = 0.09f;
            CreateHighlightLine(
                root.transform,
                "North",
                new Vector3(0f, 0f, extent),
                new Vector3(extent * 2f + width, 0.025f, width),
                material);
            CreateHighlightLine(
                root.transform,
                "South",
                new Vector3(0f, 0f, -extent),
                new Vector3(extent * 2f + width, 0.025f, width),
                material);
            CreateHighlightLine(
                root.transform,
                "East",
                new Vector3(extent, 0f, 0f),
                new Vector3(width, 0.025f, extent * 2f + width),
                material);
            CreateHighlightLine(
                root.transform,
                "West",
                new Vector3(-extent, 0f, 0f),
                new Vector3(width, 0.025f, extent * 2f + width),
                material);
            return root;
        }

        private static void CreateHighlightLine(
            Transform parent,
            string name,
            Vector3 position,
            Vector3 scale,
            Material material)
        {
            var line = CreatePrimitive(
                name,
                PrimitiveType.Cube,
                parent,
                material);
            line.transform.localPosition = position;
            line.transform.localScale = scale;
            var renderer = line.GetComponent<Renderer>();
            renderer.shadowCastingMode = ShadowCastingMode.Off;
            renderer.receiveShadows = false;
        }

        private static void CreateLobbyPart(
            string name,
            Transform parent,
            Vector3 position,
            Vector3 scale,
            Material material)
        {
            var value = GameObject.CreatePrimitive(PrimitiveType.Cube);
            value.name = name;
            value.transform.SetParent(parent, false);
            value.transform.localPosition = position;
            value.transform.localScale = scale;
            value.GetComponent<Renderer>().sharedMaterial = material;
        }

        private static void EnsureFolder(string path)
        {
            if (AssetDatabase.IsValidFolder(path))
            {
                return;
            }
            var slash = path.LastIndexOf('/');
            var parent = path.Substring(0, slash);
            EnsureFolder(parent);
            AssetDatabase.CreateFolder(parent, path.Substring(slash + 1));
        }
    }
